INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷102·隐帝本纪·乾祐二年九月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/20d5546bb3510d89dd7f3f66087f55d50b7752ed/content/books/zizhi-tongjian/vol-288/year-0949/part-04/sources/library/jiuwudaishi-102-september-949/source.txt", "note": "《旧五代史》卷102·隐帝本纪·乾祐二年九月，段落 jiu-wudaishi-205deb4a7860-p002477；已核上下文及传主，纸本及异文待核。", "id": "91eb68a3-3957-55b7-962a-8fb9e4be5cd5"}, {"title": "旧五代史·卷110·周太祖纪·乾祐二年八月返京", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/20d5546bb3510d89dd7f3f66087f55d50b7752ed/content/books/zizhi-tongjian/vol-288/year-0949/part-04/sources/library/jiuwudaishi-110-return-court-949/source.txt", "note": "《旧五代史》卷110·周太祖纪·乾祐二年八月返京，段落 jiu-wudaishi-205deb4a7860-p002636；已核上下文及传主，纸本及异文待核。", "id": "393a6c8f-d7a4-5dc9-8d5f-6a6b81a64875"}, {"title": "资治通鉴·卷288·乾祐二年·八月至十二月", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/20d5546bb3510d89dd7f3f66087f55d50b7752ed/content/books/zizhi-tongjian/vol-288/year-0949/part-04/sources/library/tongjian-288-949-august-december/source.txt", "note": "《资治通鉴》卷288·乾祐二年·八月至十二月，段落 zizhi-tongjian-a63549944a71-p003425；已核上下文及传主，纸本及异文待核。", "id": "bf2b74b2-dd3d-5a7c-b003-9f3556a7ff38"}, {"title": "新五代史·卷46·王建立传附王守恩·欧阳修论", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/20d5546bb3510d89dd7f3f66087f55d50b7752ed/content/books/zizhi-tongjian/vol-288/year-0949/part-04/sources/library/xinwudaishi-046-ouyang-commentary/source.txt", "note": "《新五代史》卷46·王建立传附王守恩·欧阳修论，段落 xin-wudaishi-b08f244b9241-p001744；已核上下文及传主，纸本及异文待核。", "id": "314fe593-649c-5343-b4c5-ecdd7b11d46e"}, {"title": "新五代史·卷66·楚世家·仆射洲之战及后续", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/20d5546bb3510d89dd7f3f66087f55d50b7752ed/content/books/zizhi-tongjian/vol-288/year-0949/part-04/sources/library/xinwudaishi-066-pushezhou/source.txt", "note": "《新五代史》卷66·楚世家·仆射洲之战及后续，段落 xin-wudaishi-b08f244b9241-p003329；已核上下文及传主，纸本及异文待核。", "id": "1de76302-3d97-5251-886d-6cba3e293c85"}, {"title": "资治通鉴·卷288·乾祐二年·六月至八月", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/69dcf8a2fbba2850268b5fe5a8e94410a672cacd/content/books/zizhi-tongjian/vol-288/year-0949/part-02/sources/library/tongjian-288-949-june-july/source.txt", "note": "《资治通鉴》卷288·乾祐二年·六月至八月，段落 zizhi-tongjian-a63549944a71-p003424；已核上下文及传主，纸本及异文待核。", "id": "a9b57512-1ba4-5b10-b3c3-6a8f96e53250"}, {"title": "旧五代史·卷125·王守恩传·洛阳聚敛与被替换", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/2d42e21ad1bb401f000e13eff449c033474939df/content/books/zizhi-tongjian/vol-288/year-0949/part-03/sources/library/jiuwudaishi-125-wang-shouen-luoyang/source.txt", "note": "《旧五代史》卷125·王守恩传·洛阳聚敛与被替换，段落 jiu-wudaishi-205deb4a7860-p002915；已核上下文及传主，纸本及异文待核。", "id": "d2c3a64e-3a3b-50ec-84e8-b9e06acd8864"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "王守恩", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "王建立的儿子，与张从恩是姻亲。947年在上党，以左骁卫大将军身份被张从恩暂派为巡检使，协助赵行迁。姻亲具体双方未明，不补具体婚配，生卒年未载。", "biography": null, "status": "draft", "id": "72fe9a16-4716-54d0-bc82-5e7feadc013e"}, {"name": "刘承祐", "aliases": ["劉承祐", "后汉隐帝"], "era": "五代十国", "birth_year": 931, "death_year": null, "description": "刘知远第二子，母亲为李氏。《旧五代史》记他生于931年三月七日的邺都旧宅，曾任左卫大将军和大内都点检。948年二月先封周王，随后依据公布的遗制继承后汉皇位。《资治通鉴》记其即位时十八岁。", "biography": null, "status": "draft", "id": "96b54cac-772d-54e8-b2de-975b3be49e85"}, {"name": "马希萼", "aliases": ["馬希萼"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "马希范的弟弟、马希广的兄长。947年马希范死时，任武平节度使、知永州事，部分将领主张拥立他，但最终马希广继位。生卒年尚未录入。", "biography": null, "status": "draft", "id": "9d5be246-b5ae-553e-b5c5-a6a875b2c1cd"}, {"name": "苑氏（马希萼妻）", "aliases": ["苑氏"], "era": "五代十国", "birth_year": null, "death_year": 949, "description": "马希萼的妻子，个人名字与生年未载。949年劝丈夫不要与兄弟交战，未被听从；马希萼战败归来后，投井而死。未因同姓与苑玫等人建立亲属关系。", "biography": null, "status": "draft", "id": "058eabc0-d241-553c-8716-8bc00622fa07"}, {"name": "马希广", "aliases": ["馬希廣", "德丕"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：马希广，武安节度副使，临时领府者。", "biography": null, "status": "draft", "id": "eb8e4d76-8384-56ed-a225-77675cfd8927"}, {"name": "刘彦瑫", "aliases": ["劉彥瑫"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚国长直都指挥使。947年与李弘皋等主张拥立马希广，五月乙未称马希范遗命，拥立马希广。生卒年未载。", "biography": null, "status": "draft", "id": "56a833a2-40b7-516a-baac-d3f00b328727"}, {"name": "李弘皋", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚王马希范的幕僚，939年天策府开府时获任学士。生卒年未载。", "biography": null, "status": "draft", "id": "87806f3c-0c40-510b-b333-2e0b18bc54da"}, {"name": "王赟（楚岳州刺史）", "aliases": ["王赟", "王贇"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "王环的儿子，楚国岳州刺史。949年受马希广任命为都部署战棹指挥使，在仆射洲击败马希萼，追击时奉马希广命令撤回。生卒年尚未录入。", "biography": null, "status": "draft", "id": "31c5b9cf-6cb4-5f96-a891-18f490536385"}, {"name": "王环", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷269乾化四年条所见人物：王环。", "biography": null, "status": "draft", "id": "6a6bb82a-8b0a-5492-a34a-772c01702860"}, {"name": "郭威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：郭威。", "biography": null, "status": "draft", "id": "3fe84db3-aa25-5be9-9dd3-8b46e28213af"}, {"name": "杨邠", "aliases": ["楊邠"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "冠氏人，947年二月任河东都押牙，与郭威共同劝刘知远接受称帝建议。生卒年暂未录入。", "biography": null, "status": "draft", "id": "eede7986-584c-5c2a-9c1c-39a3959f1291"}, {"name": "史弘肇", "aliases": ["史宏肇"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "荥泽人，947年二月任刘知远的武节都指挥使，奉命在球场集合各军，宣布出兵日期。《旧五代史》亦有史宏肇的字形。生卒年暂未录入。", "biography": null, "status": "draft", "id": "c36d0d69-d2db-5ee8-9bf6-80791eb21dda"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "郭威用枢密使文书命白文珂接替王守恩", "start_year": 949, "end_year": 949, "time_original": "949年八月甲申", "dynasty": "五代十国", "description": "郭威用枢密使文书命白文珂接替王守恩。", "phases": [], "location_name": "洛阳", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "fd2144f5-765a-5ae9-98d4-c03e45b5b295"}, {"title": "王守恩到大梁后担心获罪，献物并重贿权贵", "start_year": 949, "end_year": 949, "time_original": "949年八月被撤换留守后，具体到京日未载", "dynasty": "五代十国", "description": "王守恩到大梁后担心获罪，献物并重贿权贵。", "phases": [], "location_name": "大梁", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "c9652b51-3c2e-5333-ac96-7c27024ea0f9"}, {"title": "后汉朝廷念王守恩曾率潞州归附，免其罪", "start_year": 949, "end_year": 949, "time_original": "949年王守恩到大梁后，具体日未载", "dynasty": "五代十国", "description": "后汉朝廷念王守恩曾率潞州归附，免其罪。", "phases": [], "location_name": "后汉朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "0d9588cd-bd89-55ca-af9e-8094b49335ee"}, {"title": "后汉处死王守恩手下数名办事者", "start_year": 949, "end_year": 949, "time_original": "949年王守恩获宽宥时，具体日未载", "dynasty": "五代十国", "description": "后汉处死王守恩手下数名办事者。", "phases": [], "location_name": "后汉，具体行刑地点未载", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "07850e17-2c0d-5727-a0fb-6b4f1af1acfe"}, {"title": "王守恩被撤换后，向追讨财物的洛阳人逐一偿还", "start_year": 949, "end_year": 949, "time_original": "949年被撤换西京留