INSERT INTO public.fact_claim (id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status)
SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "historical_commentary", "claim_text": "欧阳修认为，郭威以枢密使文书随意撤换留守、朝廷也不追问，反映出当时法制纲纪已经败坏；他提醒治国者重视细小变化，防止逐渐失序。", "citation": "卷288·乾祐二年（949年八月至九月及史论）·zztj-v288-y0949-p023·原文件第101行", "note": "原文：欧阳修论曰：自古乱亡之国，必先坏其法制而后乱从之，此势之然也，五代之际是已。文珂、守恩皆汉大臣，而周太祖以一枢密使头子而易置之，如更戍卒。是时太祖未有无君之志，而所为如此者，盖习为常事，故文珂不敢违，守恩不敢拒。太祖既处之不疑，而汉廷君臣亦置而不问，岂非纲纪坏乱之极而至于此欤！是以善为天下虑者，不敢忽于微而常杜其渐也，可不戒哉！；核对说明：此段是后世史家对已录949年事件的评论，关联原事件而不创建949年欧阳修参加朝政的事件。未有无君之志是欧阳修对郭威当时动机的判断，不当作已证明的内心事实。", "status": "draft", "id": "c86fa1b9-3d30-5d9b-aff2-59a7cbe75a76", "subject_id": "fd2144f5-765a-5ae9-98d4-c03e45b5b295", "source_id": "a9b57512-1ba4-5b10-b3c3-6a8f96e53250"}, {"subject_table": "event", "field_path": "historical_commentary", "claim_text": "《新五代史》也载欧阳修以枢密使文书撤换留守的事例，批评法制纲纪败坏。", "citation": "《新五代史》卷46·王建立传附王守恩·欧阳修论，段落 xin-wudaishi-b08f244b9241-p001744；已核上下文及传主，纸本及异文待核。", "note": "原文：而周太祖以一樞密使頭子易置之，如更戍卒。；核对说明：《通鉴》节引同一史论，两处是同一作者论述的传承，不作为两个独立来源证明郭威的政治动机。", "status": "draft", "id": "8b842176-7cc6-5f31-95c8-2d95584c227e", "subject_id": "fd2144f5-765a-5ae9-98d4-c03e45b5b295", "source_id": "314fe593-649c-5343-b4c5-ecdd7b11d46e"}, {"subject_table": "event", "field_path": "description", "claim_text": "王守恩到大梁后担心获罪，献物并重贿权贵。", "citation": "卷288·乾祐二年（949年八月至九月及史论）·zztj-v288-y0949-p024·原文件第102行", "note": "原文：守恩至大梁，恐获罪，广为贡献，重赂权贵。；核对说明：未载受贿者具体姓名、金额或逐次交易，不把所有权臣都认定为收贿者。", "status": "draft", "id": "d0e1cd0b-7f24-5274-a3b2-edee661b0de3", "subject_id": "c9652b51-3c2e-5333-ac96-7c27024ea0f9", "source_id": "bf2b74b2-dd3d-5a7c-b003-9f3556a7ff38"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "949年八月被撤换留守后，具体到京日未载", "citation": "卷288·乾祐二年（949年八月至九月及史论）·zztj-v288-y0949-p024·原文件第102行", "note": "原文：守恩至大梁，恐获罪，广为贡献，重赂权贵。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "ed2f6a17-6235-5646-896d-cc57b9ed7b65", "subject_i